80		 * for a request that has already timed out. The InteractionGrpcService
81		 * uses this to convert a tracker-induced DEFER_TIMEOUT into OK so the
82		 * SDK doesn't set deferFailed=true on a defer that actually succeeded.
83		 */
84		setOnLateSuccess(cb: (request_id: string, response: MessageResponseIPC) => void): void {
85			this.onLateSuccess = cb;
86		}
87	
