89		 * Track a request and return a promise that resolves when the response arrives
90		 */
91		trackRequest(request_id: string, timeoutMs?: number): Promise<MessageResponseIPC> {
92			// Collision: reject the previous holder immediately and clear its
93			// timer before installing the new one. Without this, the prior
94			// promise would leak until its 30s timer fires AND its expiry would
95			// delete the NEW entry — making the new caller's response land as
96			// "Received response for unknown request" and itself time out.
97			const prior = this.pendingRequests.get(request_id);
98			if (prior) {
99				clearTimeout(prior.timeout);
100				this.pendingRequests.delete(request_id);
101				prior.reject(new Error(`Request ${request_id} superseded by a new tracker entry (trace_id collision)`));
