103				logger.warn(LogType.CLUSTER, `Request ${request_id} was already tracked — rejected the prior promise`);
104			}
105	
106			return new Promise<MessageResponseIPC>((resolve, reject) => {
107				const timeout = setTimeout(() => {
108					this.pendingRequests.delete(request_id);
109					this.onSettle?.(request_id);
110					reject(new Error(`Request ${request_id} timed out after ${timeoutMs || this.defaultTimeout}ms`));
111				}, timeoutMs || this.defaultTimeout);
112	
113				this.pendingRequests.set(request_id, {
114					resolve,
115					reject,
116					timeout,
117					timestamp: Date.now()
118				});
119	
120				logger.info(
121					LogType.CLUSTER,
122					`Tracking request ${request_id} with timeout ${timeoutMs || this.defaultTimeout}ms`
123				);
124			});
125		}
