131			const pending = this.pendingRequests.get(request_id);
132			if (!pending) {
133				// Audit 1.6: a success response arriving AFTER the tracker
134				// timed out used to be dropped silently. We now keep a
135				// bounded ring of late successes and fire the onLateSuccess
136				// hook so the caller can convert the timeout into OK. A
137				// failure response is still discarded — letting late
138				// failures slip through would let a real defer failure
139				// masquerade as a late success.
