143					this.onLateSuccess?.(request_id, response);
144				} else {
145					logger.warn(LogType.CLUSTER, `Received response for unknown request ${request_id}`);
146				}
147				return false;
148			}
149	
150			clearTimeout(pending.timeout);
151			this.pendingRequests.delete(request_id);
152			this.onSettle?.(request_id);
153	
154			const duration = Date.now() - pending.timestamp;
155			logger.info(LogType.CLUSTER, `Request ${request_id} resolved in ${duration}ms`);
156	
157			pending.resolve(response);
158			return true;
159		}
