1	import type { MessageStoreWrite } from "@kena/shared";
2	
3	/**
4	 * Buffer de escritura entre los handlers del gateway y el store de mensajes de
5	 * Postgres.
6	 *
7	 * MESSAGE_CREATE es el evento más caliente del gateway. Escribir una fila por
8	 * evento con una petición HTTP a api-db costaría un round-trip por mensaje y
9	 * un INSERT por mensaje: a 5.000 msg/s eso son 5.000 peticiones/s y 5.000
10	 * transacciones/s, que no aguanta ni el servicio ni la base de datos.
11	 *
12	 * Este buffer los agrupa: acumula filas en memoria y las vuelca en lotes de
13	 * hasta `maxBatchSize` cada `flushIntervalMs`. A 5.000 msg/s con los valores
14	 * por defecto son ~10 peticiones/s con 500 filas cada una, y cada lote es UNA
15	 * sentencia (`INSERT ... FROM UNNEST(...)`).
16	 *
17	 * ── Qué se pierde y por qué es aceptable ─────────────────────────────────────
18	 * El buffer vive en memoria del worker. Si el proceso muere de forma abrupta
19	 * (SIGKILL, OOM) se pierde lo acumulado desde el último flush: como mucho
20	 * `flushIntervalMs` de mensajes. En una parada ordenada no se pierde nada,
21	 * porque `shutdown()` vacía lo pendiente antes de salir. Se eligió esto frente
22	 * a un Redis Stream con consumer group porque el objetivo de todo el cambio es
23	 * QUITAR carga de Redis, y un stream la volvería a meter.
24	 *
25	 * ── Coalescencia ─────────────────────────────────────────────────────────────
26	 * Las filas se indexan por id de mensaje, no se encolan en lista. Si un mensaje
27	 * se crea y se edita dentro de la misma ventana de flush, sale una sola fila
28	 * con el estado final en vez de dos escrituras que compiten. Es además lo que
29	 * evita el error de Postgres "ON CONFLICT DO UPDATE command cannot affect row a
30	 * second time" cuando la misma clave aparece dos veces en la misma sentencia
31	 * (el repositorio tiene además su propio `DISTINCT ON` como red de seguridad).
32	 */
33	
34	export interface MessageIngestLogger {
35		debug(msg: string, meta?: Record<string, unknown>): void;
36		warn(msg: string, meta?: Record<string, unknown>): void;
37		error(msg: string, meta?: Record<string, unknown>): void;
38	}
39	
40	export interface MessageIngestTransport {
41		/**
42		 * Escribe un lote. Debe resolver a `false` si el destino lo rechazó ENTERO.
43		 *
44		 * El número que devuelve, cuando lo devuelve, es cuántas filas rechazó el
45		 * servidor una a una habiendo escrito el resto: eso NO es un fallo del lote,
46		 * solo se contabiliza.
47		 */
48		writeBatch(rows: MessageStoreWrite[]): Promise<boolean | { ok: boolean; rejected?: number }>;
49		/** Marca ids como borrados. Debe resolver a `false` si el destino lo rechazó. */
50		markDeleted(ids: string[]): Promise<boolean | { ok: boolean; rejected?: number }>;
51	}
52	
53	export interface MessageIngestBufferOptions {
54		/** Master switch. Con `false` el buffer acepta y descarta: nada llega a Postgres. */
55		enabled?: boolean;
56		/** Cada cuánto se vuelca lo acumulado. Por defecto 500 ms. */
57		flushIntervalMs?: number;
58		/** Filas por petición. Por defecto 500 (el servidor acepta hasta 1.000). */
59		maxBatchSize?: number;
60		/**
61		 * Tope de BYTES serializados por petición. Por defecto 3 MiB.
62		 *
63		 * El tope por número de filas no basta: api-db-go corre sobre Fiber, cuyo
64		 * `BodyLimit` acota el cuerpo de la petición, y 500 mensajes ricos (embeds
65		 * llenos, 10 adjuntos) se van a ~18 MiB. El servidor contestaba 413, el
66		 * reintento fallaba igual y el lote ENTERO se descartaba — 500 mensajes
67		 * perdidos, en silencio salvo por un log de error.
68		 *
69		 * 3 MiB deja margen holgado bajo el límite del servidor para cabeceras y para
70		 * la diferencia entre esta estimación y el JSON final.
71		 */
72		maxBatchBytes?: number;
73		/**
74		 * Tope duro de filas en memoria. Si api-db está caído, sin este tope el
75		 * buffer crecería hasta agotar el heap del worker y tumbar el bot por un
76		 * fallo de un servicio auxiliar. Al llegar al tope se descartan las filas
77		 * NUEVAS y se cuentan en `droppedMessages`. Por defecto 20.000 filas
78		 * (~40 s de margen a 500 msg/s).
79		 */
80		maxBufferedMessages?: number;
81		/** Mismo tope para los ids pendientes de marcar como borrados. */
82		maxBufferedDeletes?: number;
83	}
84	
85	// `type` y no `interface` a propósito: los alias de tipo obtienen firma de
86	// índice implícita, así que un `MessageIngestStats` se puede pasar donde se
87	// espera `Record<string, unknown>` — que es exactamente lo que pide el `meta`
88	// del logger. Una interface no lo permitiría.
89	export type MessageIngestStats = {
90		/** Filas aceptadas por el buffer desde el arranque. */
91		enqueued: number;
92		/** Filas confirmadas por api-db. */
93		flushed: number;
94		/** Filas descartadas por tope de buffer o por fallo tras reintento. */
95		droppedMessages: number;
96		/** Ids de borrado descartados por tope de buffer o por fallo tras reintento. */
97		droppedDeletes: number;
98		/** Lotes que fallaron (incluye los que luego el reintento salvó). */
99		failedBatches: number;
100		/** Filas esperando ahora mismo. */
101		pendingMessages: number;
102		/** Ids de borrado esperando ahora mismo. */
103		pendingDeletes: number;
104		/** Filas que el servidor rechazó una a una sin tumbar su lote. */
105		rejectedMessages: number;
106		/** Filas descartadas aquí por no caber ellas solas en `maxBatchBytes`. */
107		oversizedMessages: number;
108	};
109	
110	const DEFAULTS = {
111		enabled: true,
112		flushIntervalMs: 500,
113		maxBatchSize: 500,
114		maxBatchBytes: 3 * 1024 * 1024,
115		maxBufferedMessages: 20_000,
116		maxBufferedDeletes: 20_000
117	} as const;
118	
119	export class MessageIngestBuffer {
120		private readonly transport: MessageIngestTransport;
121		private readonly logger: MessageIngestLogger;
122		private readonly options: Required<MessageIngestBufferOptions>;
123	
124		/** Map en vez de array: coalesce por id y conserva el orden de inserción. */
125		private readonly pending = new Map<string, MessageStoreWrite>();
126		private readonly pendingDeletes = new Set<string>();
127	
128		private timer: NodeJS.Timeout | null = null;
129		private flushing = false;
130		private stopped = false;
131	
132		private stats = {
133			enqueued: 0,
134			flushed: 0,
135			droppedMessages: 0,
136			droppedDeletes: 0,
137			failedBatches: 0,
138			rejectedMessages: 0,
139			oversizedMessages: 0
140		};
141	
142		constructor(
143			transport: MessageIngestTransport,
144			logger: MessageIngestLogger,
145			options: MessageIngestBufferOptions = {}
146		) {
147			this.transport = transport;
148			this.logger = logger;
149			this.options = { ...DEFAULTS, ...options };
150		}
151	
152		start(): void {
153			if (this.timer || !this.options.enabled) return;
154			this.stopped = false;
155			this.timer = setInterval(() => {
156				void this.flush();
157			}, this.options.flushIntervalMs);
158			// El intervalo no debe mantener vivo el event loop: si todo lo demás
159			// terminó, el proceso tiene que poder salir.
160			this.timer.unref?.();
161		}
162	
163		/**
164		 * Encola un mensaje. Nunca lanza ni espera: los handlers del gateway están
165		 * en la ruta caliente y no pueden bloquearse por el store.
166		 */
167		add(row: MessageStoreWrite): void {
168			if (!this.options.enabled || this.stopped) return;
169	
170			const existing = this.pending.get(row.id);
171			if (existing) {
172				// Fusión sobre lo pendiente en lugar de reemplazo: los payloads de
173				// MESSAGE_UPDATE son parciales por contrato, así que un reemplazo
174				// directo perdería campos que solo traía el MESSAGE_CREATE.
175				this.pending.set(row.id, mergeRow(existing, row));
176				return;
177			}
178	
179			if (this.pending.size >= this.options.maxBufferedMessages) {
180				this.stats.droppedMessages++;
181				return;
182			}
183	
184			this.pending.set(row.id, row);
185			this.stats.enqueued++;
186	
187			// Volcado anticipado por tamaño: sin esto, una ráfaga por encima de
188			// `maxBatchSize` esperaría igualmente al tick y el lote crecería sin
189			// control entre ticks.
190			if (this.pending.size >= this.options.maxBatchSize) void this.flush();
191		}
192	
193		/**
194		 * Devuelve la fila que sigue esperando en el buffer, si la hay.
195		 *
196		 * Cubre la ventana ciega entre escribir un mensaje y que llegue a Postgres
197		 * (como mucho `flushIntervalMs`). Sin esto, editar o borrar un mensaje
198		 * recién enviado buscaría en Postgres una fila que todavía no está escrita y
199		 * el evento saldría sin cuerpo previo. Es una lectura de un Map en memoria:
200		 * ni round-trip ni coste apreciable.
201		 */
202		peek(id: string): MessageStoreWrite | undefined {
203			return this.pending.get(id);
204		}
205	
206		/** Encola el marcado de borrado de uno o varios mensajes. */
207		remove(ids: string | string[]): void {
208			if (!this.options.enabled || this.stopped) return;
209	
210			for (const id of Array.isArray(ids) ? ids : [ids]) {
211				if (this.pendingDeletes.size >= this.options.maxBufferedDeletes) {
212					this.stats.droppedDeletes++;
213					continue;
214				}
215				this.pendingDeletes.add(id);
216			}
217	
218			if (this.pendingDeletes.size >= this.options.maxBatchSize) void this.flush();
219		}
220	
221		/**
222		 * Vuelca un lote de mensajes y otro de borrados.
223		 *
224		 * Reentrante-seguro: si ya hay un flush en vuelo, esta llamada retorna sin
225		 * hacer nada. Sin esa guarda, un pico dispararía flushes concurrentes que
226		 * competirían por las mismas filas y multiplicarían las peticiones en vuelo
227		 * justo cuando api-db va peor.
228		 */
229		async flush(): Promise<void> {
230			if (this.flushing) return;
231			if (this.pending.size === 0 && this.pendingDeletes.size === 0) return;
232	
233			this.flushing = true;
234			try {
235				await this.flushMessages();
236				await this.flushDeletes();
237			} finally {
238				this.flushing = false;
239			}
240		}
241	
242		private async flushMessages(): Promise<void> {
243			if (this.pending.size === 0) return;
244	
245			const batch: MessageStoreWrite[] = [];
246			let bytes = 0;
247			for (const [id, row] of this.pending) {
248				if (batch.length >= this.options.maxBatchSize) break;
249	
250				const size = rowByteSize(row);
251	
252				// Una fila que ella sola pasa del tope no cabe en NINGÚN lote: dejarla
253				// en el Map la convertiría en un bloqueo permanente de la cabecera de
254				// la cola, porque la iteración empieza siempre por el principio. Se
255				// descarta y se cuenta. No debería pasar nunca: Discord acota mensaje,
256				// embeds y adjuntos muy por debajo de 3 MiB.
257				if (size > this.options.maxBatchBytes) {
258					this.pending.delete(id);
259					this.stats.oversizedMessages++;
260					this.stats.droppedMessages++;
261					this.logger.warn("Message dropped: single row over the batch byte budget", {
262						id,
263						size,
264						limit: this.options.maxBatchBytes
265					});
266					continue;
267				}
268	
269				// El corte por bytes va DESPUÉS de haber metido al menos una fila, para
270				// que un lote nunca salga vacío.
271				if (batch.length > 0 && bytes + size > this.options.maxBatchBytes) break;
272	
273				batch.push(row);
274				bytes += size;
275				this.pending.delete(id);
276			}
277			if (batch.length === 0) return;
278	
279			const outcome = await this.attempt(() => this.transport.writeBatch(batch), "writeBatch");
280			if (outcome.ok) {
281				this.stats.flushed += batch.length - outcome.rejected;
282				if (outcome.rejected > 0) {
283					this.stats.rejectedMessages += outcome.rejected;
284					this.stats.droppedMessages += outcome.rejected;
285					this.logger.warn("Message rows rejected individually by api-db", {
286						rejected: outcome.rejected,
287						batch: batch.length
288					});
289				}
290				return;
291			}
292	
293			// El lote se pierde. Reencolarlo parece más amable pero es peor: con
294			// api-db caído las filas reencoladas se acumulan hasta el tope y acaban
295			// descartadas igual, solo que después de haber bloqueado el buffer a
296			// mensajes nuevos y de haber reintentado indefinidamente. Se cuenta la
297			// pérdida y se sigue aceptando tráfico fresco.
298			this.stats.droppedMessages += batch.length;
299			// Bajado a debug: con api-db caído esto escupía una línea por lote. La
300			// pérdida sigue contabilizada en `stats.droppedMessages`.
301			this.logger.debug("Message batch dropped after retry", {
302				size: batch.length,
303				dropped_total: this.stats.droppedMessages
304			});
305		}
306	
307		private async flushDeletes(): Promise<void> {
308			if (this.pendingDeletes.size === 0) return;
309	
310			const batch: string[] = [];
311			for (const id of this.pendingDeletes) {
312				if (batch.length >= this.options.maxBatchSize) break;
313				// Un id cuya fila sigue esperando a escribirse NO se manda todavía:
314				// `markDeleted` es un UPDATE, así que correr antes que el INSERT no
315				// afectaría a ninguna fila y la marca de borrado se perdería para
316				// siempre.
317				//
318				// Lo normal es que la fila ya haya salido: `flush()` ESPERA a
319				// `flushMessages` antes de llegar aquí. Esta guarda cubre el caso en
320				// que no cupo — el lote se cortó por `maxBatchSize` o por
321				// `maxBatchBytes` —, y entonces el id sale en el ciclo siguiente.
322				if (this.pending.has(id)) continue;
323				batch.push(id);
324				this.pendingDeletes.delete(id);
325			}
326			if (batch.length === 0) return;
327	
328			const outcome = await this.attempt(() => this.transport.markDeleted(batch), "markDeleted");
329			if (!outcome.ok) {
330				this.stats.droppedDeletes += batch.length;
331				this.logger.error("Message delete batch dropped after retry", {
332					size: batch.length,
333					dropped_total: this.stats.droppedDeletes
334				});
335			}
336		}
337	
338		/**
339		 * Un único reintento inmediato. Cubre el caso realista (un reinicio de
340		 * api-db, un corte de red de un segundo) sin convertirse en una tormenta de
341		 * reintentos que empeoraría una caída real.
342		 */
343		private async attempt(
344			operation: () => Promise<boolean | { ok: boolean; rejected?: number }>,
345			label: string
346		): Promise<{ ok: boolean; rejected: number }> {
347			for (let attempt = 1; attempt <= 2; attempt++) {
348				try {
349					const res = await operation();
350					const ok = typeof res === "boolean" ? res : res.ok;
351					if (ok) return { ok: true, rejected: typeof res === "boolean" ? 0 : (res.rejected ?? 0) };
352				} catch (error) {
353					this.logger.debug(`Message ingest ${label} threw`, {
354						attempt,
355						error: error instanceof Error ? error.message : String(error)
356					});
357				}
358				if (attempt === 1) this.stats.failedBatches++;
359			}
360			return { ok: false, rejected: 0 };
361		}
362	
363		/**
364		 * Parada ordenada: vacía todo lo pendiente dentro del presupuesto de tiempo
365		 * y deja de aceptar nuevo tráfico.
366		 *
367		 * `deadlineMs` acota el trabajo porque el master mata al worker pasado su
368		 * propio timeout de apagado; agotarlo aquí impediría el resto de la limpieza
369		 * (cierre de Redis, flush de GlitchTip).
370		 */
371		async shutdown(deadlineMs = 3_000): Promise<MessageIngestStats> {
372			this.stopped = true;
373			if (this.timer) {
374				clearInterval(this.timer);
375				this.timer = null;
376			}
377	
378			const deadline = Date.now() + deadlineMs;
379			while ((this.pending.size > 0 || this.pendingDeletes.size > 0) && Date.now() < deadline) {
380				const before = this.pending.size + this.pendingDeletes.size;
381				await this.flush();
382				// Sin progreso (api-db no responde) no tiene sentido seguir gastando
383				// el presupuesto de apagado dando vueltas.
384				if (this.pending.size + this.pendingDeletes.size >= before) break;
385			}
386	
387			const remaining = this.pending.size + this.pendingDeletes.size;
388			if (remaining > 0) {
389				this.logger.warn("Message ingest buffer shut down with pending rows", { remaining });
390			}
391	
392			return this.getStats();
393		}
394	
395		getStats(): MessageIngestStats {
396			return {
397				...this.stats,
398				pendingMessages: this.pending.size,
399				pendingDeletes: this.pendingDeletes.size
400			};
401		}
402	}
403	
404	/**
405	 * Bytes que ocupará la fila en el JSON de la petición.
406	 *
407	 * Se mide con `JSON.stringify` sobre la fila, que es exactamente lo que va a
408	 * viajar. Es más caro que estimar por longitudes de campo, pero se paga una vez
409	 * por fila y por flush (no por evento del gateway), y una estimación por lo bajo
410	 * devolvería el 413 que este cálculo existe para evitar.
411	 *
412	 * `Buffer.byteLength` y no `.length`: el tope del servidor es en bytes, y un
413	 * mensaje en japonés o lleno de emoji ocupa 3-4 bytes por carácter.
414	 */
415	function rowByteSize(row: MessageStoreWrite): number {
416		try {
417			return Buffer.byteLength(JSON.stringify(row), "utf8");
418		} catch {
419			// Una fila que ni siquiera serializa (referencia circular) no puede
420			// enviarse. Devolver Infinity la manda por la rama de "no cabe en ningún
421			// lote", que la descarta con un aviso en vez de reventar el flush.
422			return Number.POSITIVE_INFINITY;
423		}
424	}
425	
426	/**
427	 * Copia sobre `base` los campos DEFINIDOS de `next`. Un `undefined` en `next`
428	 * significa "el payload no traía este campo", no "ponlo a vacío"; un spread
429	 * normal lo machacaría y borraría datos que sí tenía el evento anterior.
430	 */
431	function mergeRow(base: MessageStoreWrite, next: MessageStoreWrite): MessageStoreWrite {
432		// El doble salto por `unknown` es necesario: `MessageStoreWrite` es una
433		// interface sin firma de índice, así que TypeScript no la considera
434		// suficientemente solapada con `Record<string, unknown>` para un cast
435		// directo. La escritura por clave sí es segura — las claves salen de
436		// `Object.entries(next)`, o sea del propio tipo.
437		const merged = { ...base } as unknown as Record<string, unknown>;
438		for (const [key, value] of Object.entries(next)) {
439			if (value !== undefined) merged[key] = value;
440		}
441		return merged as unknown as MessageStoreWrite;
442	}
