import type { MessageStoreWrite } from "@kena/shared";

/**
 * Buffer de escritura entre los handlers del gateway y el store de mensajes de
 * Postgres.
 *
 * MESSAGE_CREATE es el evento más caliente del gateway. Escribir una fila por
 * evento con una petición HTTP a api-db costaría un round-trip por mensaje y
 * un INSERT por mensaje: a 5.000 msg/s eso son 5.000 peticiones/s y 5.000
 * transacciones/s, que no aguanta ni el servicio ni la base de datos.
 *
 * Este buffer los agrupa: acumula filas en memoria y las vuelca en lotes de
 * hasta `maxBatchSize` cada `flushIntervalMs`. A 5.000 msg/s con los valores
 * por defecto son ~10 peticiones/s con 500 filas cada una, y cada lote es UNA
 * sentencia (`INSERT ... FROM UNNEST(...)`).
 *
 * ── Qué se pierde y por qué es aceptable ─────────────────────────────────────
 * El buffer vive en memoria del worker. Si el proceso muere de forma abrupta
 * (SIGKILL, OOM) se pierde lo acumulado desde el último flush: como mucho
 * `flushIntervalMs` de mensajes. En una parada ordenada no se pierde nada,
 * porque `shutdown()` vacía lo pendiente antes de salir. Se eligió esto frente
 * a un Redis Stream con consumer group porque el objetivo de todo el cambio es
 * QUITAR carga de Redis, y un stream la volvería a meter.
 *
 * ── Coalescencia ─────────────────────────────────────────────────────────────
 * Las filas se indexan por id de mensaje, no se encolan en lista. Si un mensaje
 * se crea y se edita dentro de la misma ventana de flush, sale una sola fila
 * con el estado final en vez de dos escrituras que compiten. Es además lo que
 * evita el error de Postgres "ON CONFLICT DO UPDATE command cannot affect row a
 * second time" cuando la misma clave aparece dos veces en la misma sentencia
 * (el repositorio tiene además su propio `DISTINCT ON` como red de seguridad).
 */

export interface MessageIngestLogger {
	debug(msg: string, meta?: Record<string, unknown>): void;
	warn(msg: string, meta?: Record<string, unknown>): void;
	error(msg: string, meta?: Record<string, unknown>): void;
}

export interface MessageIngestTransport {
	/**
	 * Escribe un lote. Debe resolver a `false` si el destino lo rechazó ENTERO.
	 *
	 * El número que devuelve, cuando lo devuelve, es cuántas filas rechazó el
	 * servidor una a una habiendo escrito el resto: eso NO es un fallo del lote,
	 * solo se contabiliza.
	 */
	writeBatch(rows: MessageStoreWrite[]): Promise<boolean | { ok: boolean; rejected?: number }>;
	/** Marca ids como borrados. Debe resolver a `false` si el destino lo rechazó. */
	markDeleted(ids: string[]): Promise<boolean | { ok: boolean; rejected?: number }>;
}

export interface MessageIngestBufferOptions {
	/** Master switch. Con `false` el buffer acepta y descarta: nada llega a Postgres. */
	enabled?: boolean;
	/** Cada cuánto se vuelca lo acumulado. Por defecto 500 ms. */
	flushIntervalMs?: number;
	/** Filas por petición. Por defecto 500 (el servidor acepta hasta 1.000). */
	maxBatchSize?: number;
	/**
	 * Tope de BYTES serializados por petición. Por defecto 3 MiB.
	 *
	 * El tope por número de filas no basta: api-db-go corre sobre Fiber, cuyo
	 * `BodyLimit` acota el cuerpo de la petición, y 500 mensajes ricos (embeds
	 * llenos, 10 adjuntos) se van a ~18 MiB. El servidor contestaba 413, el
	 * reintento fallaba igual y el lote ENTERO se descartaba — 500 mensajes
	 * perdidos, en silencio salvo por un log de error.
	 *
	 * 3 MiB deja margen holgado bajo el límite del servidor para cabeceras y para
	 * la diferencia entre esta estimación y el JSON final.
	 */
	maxBatchBytes?: number;
	/**
	 * Tope duro de filas en memoria. Si api-db está caído, sin este tope el
	 * buffer crecería hasta agotar el heap del worker y tumbar el bot por un
	 * fallo de un servicio auxiliar. Al llegar al tope se descartan las filas
	 * NUEVAS y se cuentan en `droppedMessages`. Por defecto 20.000 filas
	 * (~40 s de margen a 500 msg/s).
	 */
	maxBufferedMessages?: number;
	/** Mismo tope para los ids pendientes de marcar como borrados. */
	maxBufferedDeletes?: number;
}

// `type` y no `interface` a propósito: los alias de tipo obtienen firma de
// índice implícita, así que un `MessageIngestStats` se puede pasar donde se
// espera `Record<string, unknown>` — que es exactamente lo que pide el `meta`
// del logger. Una interface no lo permitiría.
export type MessageIngestStats = {
	/** Filas aceptadas por el buffer desde el arranque. */
	enqueued: number;
	/** Filas confirmadas por api-db. */
	flushed: number;
	/** Filas descartadas por tope de buffer o por fallo tras reintento. */
	droppedMessages: number;
	/** Ids de borrado descartados por tope de buffer o por fallo tras reintento. */
	droppedDeletes: number;
	/** Lotes que fallaron (incluye los que luego el reintento salvó). */
	failedBatches: number;
	/** Filas esperando ahora mismo. */
	pendingMessages: number;
	/** Ids de borrado esperando ahora mismo. */
	pendingDeletes: number;
	/** Filas que el servidor rechazó una a una sin tumbar su lote. */
	rejectedMessages: number;
	/** Filas descartadas aquí por no caber ellas solas en `maxBatchBytes`. */
	oversizedMessages: number;
};

const DEFAULTS = {
	enabled: true,
	flushIntervalMs: 500,
	maxBatchSize: 500,
	maxBatchBytes: 3 * 1024 * 1024,
	maxBufferedMessages: 20_000,
	maxBufferedDeletes: 20_000
} as const;

export class MessageIngestBuffer {
	private readonly transport: MessageIngestTransport;
	private readonly logger: MessageIngestLogger;
	private readonly options: Required<MessageIngestBufferOptions>;

	/** Map en vez de array: coalesce por id y conserva el orden de inserción. */
	private readonly pending = new Map<string, MessageStoreWrite>();
	private readonly pendingDeletes = new Set<string>();

	private timer: NodeJS.Timeout | null = null;
	private flushing = false;
	private stopped = false;

	private stats = {
		enqueued: 0,
		flushed: 0,
		droppedMessages: 0,
		droppedDeletes: 0,
		failedBatches: 0,
		rejectedMessages: 0,
		oversizedMessages: 0
	};

	constructor(
		transport: MessageIngestTransport,
		logger: MessageIngestLogger,
		options: MessageIngestBufferOptions = {}
	) {
		this.transport = transport;
		this.logger = logger;
		this.options = { ...DEFAULTS, ...options };
	}

	start(): void {
		if (this.timer || !this.options.enabled) return;
		this.stopped = false;
		this.timer = setInterval(() => {
			void this.flush();
		}, this.options.flushIntervalMs);
		// El intervalo no debe mantener vivo el event loop: si todo lo demás
		// terminó, el proceso tiene que poder salir.
		this.timer.unref?.();
	}

	/**
	 * Encola un mensaje. Nunca lanza ni espera: los handlers del gateway están
	 * en la ruta caliente y no pueden bloquearse por el store.
	 */
	add(row: MessageStoreWrite): void {
		if (!this.options.enabled || this.stopped) return;

		const existing = this.pending.get(row.id);
		if (existing) {
			// Fusión sobre lo pendiente en lugar de reemplazo: los payloads de
			// MESSAGE_UPDATE son parciales por contrato, así que un reemplazo
			// directo perdería campos que solo traía el MESSAGE_CREATE.
			this.pending.set(row.id, mergeRow(existing, row));
			return;
		}

		if (this.pending.size >= this.options.maxBufferedMessages) {
			this.stats.droppedMessages++;
			return;
		}

		this.pending.set(row.id, row);
		this.stats.enqueued++;

		// Volcado anticipado por tamaño: sin esto, una ráfaga por encima de
		// `maxBatchSize` esperaría igualmente al tick y el lote crecería sin
		// control entre ticks.
		if (this.pending.size >= this.options.maxBatchSize) void this.flush();
	}

	/**
	 * Devuelve la fila que sigue esperando en el buffer, si la hay.
	 *
	 * Cubre la ventana ciega entre escribir un mensaje y que llegue a Postgres
	 * (como mucho `flushIntervalMs`). Sin esto, editar o borrar un mensaje
	 * recién enviado buscaría en Postgres una fila que todavía no está escrita y
	 * el evento saldría sin cuerpo previo. Es una lectura de un Map en memoria:
	 * ni round-trip ni coste apreciable.
	 */
	peek(id: string): MessageStoreWrite | undefined {
		return this.pending.get(id);
	}

	/** Encola el marcado de borrado de uno o varios mensajes. */
	remove(ids: string | string[]): void {
		if (!this.options.enabled || this.stopped) return;

		for (const id of Array.isArray(ids) ? ids : [ids]) {
			if (this.pendingDeletes.size >= this.options.maxBufferedDeletes) {
				this.stats.droppedDeletes++;
				continue;
			}
			this.pendingDeletes.add(id);
		}

		if (this.pendingDeletes.size >= this.options.maxBatchSize) void this.flush();
	}

	/**
	 * Vuelca un lote de mensajes y otro de borrados.
	 *
	 * Reentrante-seguro: si ya hay un flush en vuelo, esta llamada retorna sin
	 * hacer nada. Sin esa guarda, un pico dispararía flushes concurrentes que
	 * competirían por las mismas filas y multiplicarían las peticiones en vuelo
	 * justo cuando api-db va peor.
	 */
	async flush(): Promise<void> {
		if (this.flushing) return;
		if (this.pending.size === 0 && this.pendingDeletes.size === 0) return;

		this.flushing = true;
		try {
			await this.flushMessages();
			await this.flushDeletes();
		} finally {
			this.flushing = false;
		}
	}

	private async flushMessages(): Promise<void> {
		if (this.pending.size === 0) return;

		const batch: MessageStoreWrite[] = [];
		let bytes = 0;
		for (const [id, row] of this.pending) {
			if (batch.length >= this.options.maxBatchSize) break;

			const size = rowByteSize(row);

			// Una fila que ella sola pasa del tope no cabe en NINGÚN lote: dejarla
			// en el Map la convertiría en un bloqueo permanente de la cabecera de
			// la cola, porque la iteración empieza siempre por el principio. Se
			// descarta y se cuenta. No debería pasar nunca: Discord acota mensaje,
			// embeds y adjuntos muy por debajo de 3 MiB.
			if (size > this.options.maxBatchBytes) {
				this.pending.delete(id);
				this.stats.oversizedMessages++;
				this.stats.droppedMessages++;
				this.logger.warn("Message dropped: single row over the batch byte budget", {
					id,
					size,
					limit: this.options.maxBatchBytes
				});
				continue;
			}

			// El corte por bytes va DESPUÉS de haber metido al menos una fila, para
			// que un lote nunca salga vacío.
			if (batch.length > 0 && bytes + size > this.options.maxBatchBytes) break;

			batch.push(row);
			bytes += size;
			this.pending.delete(id);
		}
		if (batch.length === 0) return;

		const outcome = await this.attempt(() => this.transport.writeBatch(batch), "writeBatch");
		if (outcome.ok) {
			this.stats.flushed += batch.length - outcome.rejected;
			if (outcome.rejected > 0) {
				this.stats.rejectedMessages += outcome.rejected;
				this.stats.droppedMessages += outcome.rejected;
				this.logger.warn("Message rows rejected individually by api-db", {
					rejected: outcome.rejected,
					batch: batch.length
				});
			}
			return;
		}

		// El lote se pierde. Reencolarlo parece más amable pero es peor: con
		// api-db caído las filas reencoladas se acumulan hasta el tope y acaban
		// descartadas igual, solo que después de haber bloqueado el buffer a
		// mensajes nuevos y de haber reintentado indefinidamente. Se cuenta la
		// pérdida y se sigue aceptando tráfico fresco.
		this.stats.droppedMessages += batch.length;
		// Bajado a debug: con api-db caído esto escupía una línea por lote. La
		// pérdida sigue contabilizada en `stats.droppedMessages`.
		this.logger.debug("Message batch dropped after retry", {
			size: batch.length,
			dropped_total: this.stats.droppedMessages
		});
	}

	private async flushDeletes(): Promise<void> {
		if (this.pendingDeletes.size === 0) return;

		const batch: string[] = [];
		for (const id of this.pendingDeletes) {
			if (batch.length >= this.options.maxBatchSize) break;
			// Un id cuya fila sigue esperando a escribirse NO se manda todavía:
			// `markDeleted` es un UPDATE, así que correr antes que el INSERT no
			// afectaría a ninguna fila y la marca de borrado se perdería para
			// siempre.
			//
			// Lo normal es que la fila ya haya salido: `flush()` ESPERA a
			// `flushMessages` antes de llegar aquí. Esta guarda cubre el caso en
			// que no cupo — el lote se cortó por `maxBatchSize` o por
			// `maxBatchBytes` —, y entonces el id sale en el ciclo siguiente.
			if (this.pending.has(id)) continue;
			batch.push(id);
			this.pendingDeletes.delete(id);
		}
		if (batch.length === 0) return;

		const outcome = await this.attempt(() => this.transport.markDeleted(batch), "markDeleted");
		if (!outcome.ok) {
			this.stats.droppedDeletes += batch.length;
			this.logger.error("Message delete batch dropped after retry", {
				size: batch.length,
				dropped_total: this.stats.droppedDeletes
			});
		}
	}

	/**
	 * Un único reintento inmediato. Cubre el caso realista (un reinicio de
	 * api-db, un corte de red de un segundo) sin convertirse en una tormenta de
	 * reintentos que empeoraría una caída real.
	 */
	private async attempt(
		operation: () => Promise<boolean | { ok: boolean; rejected?: number }>,
		label: string
	): Promise<{ ok: boolean; rejected: number }> {
		for (let attempt = 1; attempt <= 2; attempt++) {
			try {
				const res = await operation();
				const ok = typeof res === "boolean" ? res : res.ok;
				if (ok) return { ok: true, rejected: typeof res === "boolean" ? 0 : (res.rejected ?? 0) };
			} catch (error) {
				this.logger.debug(`Message ingest ${label} threw`, {
					attempt,
					error: error instanceof Error ? error.message : String(error)
				});
			}
			if (attempt === 1) this.stats.failedBatches++;
		}
		return { ok: false, rejected: 0 };
	}

	/**
	 * Parada ordenada: vacía todo lo pendiente dentro del presupuesto de tiempo
	 * y deja de aceptar nuevo tráfico.
	 *
	 * `deadlineMs` acota el trabajo porque el master mata al worker pasado su
	 * propio timeout de apagado; agotarlo aquí impediría el resto de la limpieza
	 * (cierre de Redis, flush de GlitchTip).
	 */
	async shutdown(deadlineMs = 3_000): Promise<MessageIngestStats> {
		this.stopped = true;
		if (this.timer) {
			clearInterval(this.timer);
			this.timer = null;
		}

		const deadline = Date.now() + deadlineMs;
		while ((this.pending.size > 0 || this.pendingDeletes.size > 0) && Date.now() < deadline) {
			const before = this.pending.size + this.pendingDeletes.size;
			await this.flush();
			// Sin progreso (api-db no responde) no tiene sentido seguir gastando
			// el presupuesto de apagado dando vueltas.
			if (this.pending.size + this.pendingDeletes.size >= before) break;
		}

		const remaining = this.pending.size + this.pendingDeletes.size;
		if (remaining > 0) {
			this.logger.warn("Message ingest buffer shut down with pending rows", { remaining });
		}

		return this.getStats();
	}

	getStats(): MessageIngestStats {
		return {
			...this.stats,
			pendingMessages: this.pending.size,
			pendingDeletes: this.pendingDeletes.size
		};
	}
}

/**
 * Bytes que ocupará la fila en el JSON de la petición.
 *
 * Se mide con `JSON.stringify` sobre la fila, que es exactamente lo que va a
 * viajar. Es más caro que estimar por longitudes de campo, pero se paga una vez
 * por fila y por flush (no por evento del gateway), y una estimación por lo bajo
 * devolvería el 413 que este cálculo existe para evitar.
 *
 * `Buffer.byteLength` y no `.length`: el tope del servidor es en bytes, y un
 * mensaje en japonés o lleno de emoji ocupa 3-4 bytes por carácter.
 */
function rowByteSize(row: MessageStoreWrite): number {
	try {
		return Buffer.byteLength(JSON.stringify(row), "utf8");
	} catch {
		// Una fila que ni siquiera serializa (referencia circular) no puede
		// enviarse. Devolver Infinity la manda por la rama de "no cabe en ningún
		// lote", que la descarta con un aviso en vez de reventar el flush.
		return Number.POSITIVE_INFINITY;
	}
}

/**
 * Copia sobre `base` los campos DEFINIDOS de `next`. Un `undefined` en `next`
 * significa "el payload no traía este campo", no "ponlo a vacío"; un spread
 * normal lo machacaría y borraría datos que sí tenía el evento anterior.
 */
function mergeRow(base: MessageStoreWrite, next: MessageStoreWrite): MessageStoreWrite {
	// El doble salto por `unknown` es necesario: `MessageStoreWrite` es una
	// interface sin firma de índice, así que TypeScript no la considera
	// suficientemente solapada con `Record<string, unknown>` para un cast
	// directo. La escritura por clave sí es segura — las claves salen de
	// `Object.entries(next)`, o sea del propio tipo.
	const merged = { ...base } as unknown as Record<string, unknown>;
	for (const [key, value] of Object.entries(next)) {
		if (value !== undefined) merged[key] = value;
	}
	return merged as unknown as MessageStoreWrite;
}

