73	export async function startGatewayClient(
74		clusterIPC: ClusterIPC,
75		totalShards: number,
76		// El servicio de reinicio necesita el manager, no sólo el IPC: `restartCluster`
77		// (con su backoff de crash-loop y su guarda de reentrada) vive ahí.
78		clusterManager: ClusterManager
79	): Promise<void> {
80		// Circuit breakers: limits at 3x observed peak (100 req/s) over a 10s window.
81		// These fire only on runaway modules, not on normal traffic spikes.
82		//
83		// El de TASA no basta, y el incidente del 11-08-2026 lo demostró: los ~115 req/s
84		// que dejaron el core a 154 % de CPU y 10 GB quedaron muy por debajo de estos
85		// 300/s, así que nunca se activó. Lo que tumbó al core fue la ACUMULACIÓN —con
86		// 5 s de deadline y un core que ya no contestaba, del orden de 575 peticiones
87		// vivas a la vez—, no el ritmo de entrada. De ahí el techo de concurrencia.
88		//
89		// 256 en vuelo por módulo: en tráfico sano son UNIDADES (entran a ~100/s y se
90		// resuelven en decenas de ms), así que 256 es dos órdenes de magnitud de margen
91		// y jamás toca a un módulo que funciona; y está por debajo de lo que produjo el
92		// incidente, así que sí corta al desbocado. La línea de carga del minuto publica
93		// el pico real (`inFlightPeak`) para poder ajustarlo con datos en vez de a ojo.
94		const MAX_IN_FLIGHT_PER_MODULE = 256;
95	
96		const defaultRateLimiter = new GrpcRateLimiter({
97			moduleRule: { maxRequests: 3_000, windowMs: 10_000 },
98			maxInFlightPerModule: MAX_IN_FLIGHT_PER_MODULE,
99			rpcRules: {
100				// Identidad GLOBAL del bot (el usuario, no un member de servidor).
101				// Discord de verdad sólo permite un puñado de cambios de username por
