import * as grpc from "@grpc/grpc-js";
import { LogType, logger } from "../../../shared/Logger.js";

export interface RateLimitRule {
	maxRequests: number;
	windowMs: number;
}

export interface GrpcRateLimiterOptions {
	moduleRule: RateLimitRule;
	rpcRules?: Record<string, Partial<RateLimitRule>>;
	/**
	 * Techo de peticiones EN VUELO por módulo. `0` o ausente = sin techo.
	 *
	 * Es el freno que faltaba, y es distinto del de TASA: la tasa cuenta cuántas
	 * ENTRAN por ventana, y en el incidente del 11-08-2026 los ~115 req/s reales
	 * quedaron muy por debajo del techo de 300/s, así que no se activó nunca. Lo que
	 * tumbó al core no fue el ritmo de entrada: fue la ACUMULACIÓN — con 5 s de
	 * deadline y un core que ya no contestaba, llegó a tener del orden de 575
	 * peticiones vivas a la vez, cada una reteniendo su payload y su closure.
	 *
	 * En tráfico sano las peticiones en vuelo de un módulo son unidades: entran a
	 * ~100/s y se resuelven en decenas de milisegundos. Un techo alto no molesta a
	 * nadie y corta en seco al módulo desbocado, que es justo lo que se quiere —
	 * porque el core lo comparten los diez módulos y ahogarlo se los lleva a todos.
	 */
	maxInFlightPerModule?: number;
	logger?: typeof logger;
	logType?: string;
}

export interface RateLimitDecision {
	allowed: boolean;
	retryAfterMs: number;
	reason: "module" | "rpc" | "in_flight" | "none";
}

type BucketState = {
	windowStart: number;
	count: number;
};

type UnaryHandler<Req, Res> = (call: grpc.ServerUnaryCall<Req, Res>, callback: grpc.sendUnaryData<Res>) => void;

function sanitizeRule(rule: Partial<RateLimitRule> | undefined, fallback: RateLimitRule): RateLimitRule {
	const maxRequests = Number(rule?.maxRequests ?? fallback.maxRequests);
	const windowMs = Number(rule?.windowMs ?? fallback.windowMs);

	return {
		maxRequests: Number.isFinite(maxRequests) ? Math.max(1, Math.floor(maxRequests)) : fallback.maxRequests,
		windowMs: Number.isFinite(windowMs) ? Math.max(1_000, Math.floor(windowMs)) : fallback.windowMs
	};
}

export class GrpcRateLimiter {
	private readonly moduleRule: RateLimitRule;
	private readonly rpcRules: Map<string, RateLimitRule>;
	private readonly buckets = new Map<string, BucketState>();
	private readonly logger: typeof logger;
	private readonly logType: string;
	private readonly metrics = {
		allowed: 0,
		blocked: 0,
		byRpc: new Map<string, { allowed: number; blocked: number }>()
	};
	/** Peticiones vivas por módulo. Sube al admitir y baja al responder. */
	private readonly inFlight = new Map<string, number>();
	private readonly maxInFlightPerModule: number;
	/** Rechazos por techo de concurrencia en el periodo, para la línea de carga. */
	private inFlightRejections = 0;
	/** Máximo simultáneo visto en el periodo: es el número con el que calibrar. */
	private inFlightPeak = 0;

	constructor(options: GrpcRateLimiterOptions) {
		this.moduleRule = sanitizeRule(options.moduleRule, { maxRequests: 120, windowMs: 60_000 });
		this.rpcRules = new Map(
			Object.entries(options.rpcRules || {}).map(([rpc, rule]) => [rpc, sanitizeRule(rule, this.moduleRule)])
		);
		this.logger = options.logger ?? logger;
		this.logType = options.logType ?? LogType.GRPC;
		const ceiling = Number(options.maxInFlightPerModule ?? 0);
		this.maxInFlightPerModule = Number.isFinite(ceiling) && ceiling > 0 ? Math.floor(ceiling) : 0;
	}

	/**
	 * Reserva un hueco de concurrencia, o `false` si el módulo ya está en su techo.
	 *
	 * Va SEPARADO de `checkAndConsume` porque su contrapartida (`releaseInFlight`)
	 * tiene que correr cuando la petición se resuelve, y eso sólo lo sabe quien
	 * envuelve el handler. Un llamante que use `checkAndConsume` a pelo no participa
	 * del techo — es explícito, no un olvido.
	 */
	public tryAcquireInFlight(moduleKey: string): boolean {
		const live = this.inFlight.get(moduleKey) ?? 0;
		if (this.maxInFlightPerModule > 0 && live >= this.maxInFlightPerModule) {
			this.inFlightRejections++;
			return false;
		}
		const next = live + 1;
		this.inFlight.set(moduleKey, next);
		if (next > this.inFlightPeak) this.inFlightPeak = next;
		return true;
	}

	public releaseInFlight(moduleKey: string): void {
		const live = (this.inFlight.get(moduleKey) ?? 0) - 1;
		// Se borra la entrada al llegar a cero: si no, el mapa acumularía una clave
		// por cada módulo que haya hablado alguna vez desde el arranque.
		if (live <= 0) this.inFlight.delete(moduleKey);
		else this.inFlight.set(moduleKey, live);
	}

	/** Peticiones vivas de un módulo (o de todos si no se da). Para tests y métricas. */
	public getInFlight(moduleKey?: string): number {
		if (moduleKey !== undefined) return this.inFlight.get(moduleKey) ?? 0;
		let total = 0;
		for (const live of this.inFlight.values()) total += live;
		return total;
	}

	public checkAndConsume(moduleKey: string | undefined, rpcName: string): RateLimitDecision {
		const normalizedModuleKey = moduleKey?.trim() || "anonymous";
		const moduleDecision = this.consumeBucket(`mod:${normalizedModuleKey}`, this.moduleRule);
		if (!moduleDecision.allowed) {
			this.recordDecision(normalizedModuleKey, rpcName, false);
			return {
				allowed: false,
				retryAfterMs: moduleDecision.retryAfterMs,
				reason: "module"
			};
		}

		const rpcRule = this.rpcRules.get(rpcName);
		if (rpcRule) {
			const rpcDecision = this.consumeBucket(`rpc:${normalizedModuleKey}:${rpcName}`, rpcRule);
			if (!rpcDecision.allowed) {
				this.recordDecision(normalizedModuleKey, rpcName, false);
				return {
					allowed: false,
					retryAfterMs: rpcDecision.retryAfterMs,
					reason: "rpc"
				};
			}
		}

		this.recordDecision(normalizedModuleKey, rpcName, true);
		return {
			allowed: true,
			retryAfterMs: 0,
			reason: "none"
		};
	}

	public wrapUnary<Req, Res>(
		rpcName: string,
		getModuleKey: (call: grpc.ServerUnaryCall<Req, Res>) => string | undefined,
		handler: UnaryHandler<Req, Res>
	): UnaryHandler<Req, Res> {
		return (call, callback) => {
			const moduleKey = getModuleKey(call);
			const decision = this.checkAndConsume(moduleKey, rpcName);
			if (!decision.allowed) {
				const retryAfterSeconds = Math.ceil(decision.retryAfterMs / 1000);
				this.logger.warn?.(
					LogType.GRPC,
					`Rate limit exceeded for module=${moduleKey || "anonymous"} rpc=${rpcName} scope=${decision.reason}`
				);
				callback({
					code: grpc.status.RESOURCE_EXHAUSTED,
					message: `Rate limit exceeded for ${rpcName}. Retry in ${retryAfterSeconds}s`
				} as grpc.ServiceError);
				return;
			}

			// Techo de CONCURRENCIA, después del de tasa. Rechazar aquí es mucho mejor
			// para el llamante que dejarle agotar su deadline: recibe un error al
			// instante en vez de esperar 5 s a nada.
			const normalizedModuleKey = moduleKey?.trim() || "anonymous";
			if (!this.tryAcquireInFlight(normalizedModuleKey)) {
				this.logger.warn?.(
					LogType.GRPC,
					`In-flight ceiling reached for module=${normalizedModuleKey} rpc=${rpcName} (${this.maxInFlightPerModule}); request rejected`
				);
				callback({
					code: grpc.status.RESOURCE_EXHAUSTED,
					message: `Too many in-flight requests for module ${normalizedModuleKey}. Slow down.`
				} as grpc.ServiceError);
				return;
			}

			// El hueco se libera cuando la petición se resuelve, sea como sea. El guard
			// de `settled` no es paranoia: un handler que llame al callback dos veces
			// —por un `catch` que responde después de un camino que ya respondió—
			// desbalancearía el contador, y un contador que sólo sube acaba cerrando el
			// módulo entero a base de falsos «demasiadas en vuelo».
			let settled = false;
			// Los argumentos se reenvían TAL CUAL, no uno a uno: pasarlos con nombre
			// (`err, value, trailer, flags`) convertía una llamada de dos argumentos en
			// una de cuatro con dos `undefined` inventados, y eso ya cambia lo que ve
			// grpc-js — además de romper cualquier aserto sobre la forma de la respuesta.
			const release = ((...args: Parameters<grpc.sendUnaryData<Res>>): void => {
				if (!settled) {
					settled = true;
					this.releaseInFlight(normalizedModuleKey);
				}
				callback(...args);
			}) as grpc.sendUnaryData<Res>;

			// Un handler que lance de forma SÍNCRONA no llegaría a su callback nunca, y
			// el hueco se quedaría cogido para siempre.
			try {
				handler(call, release);
			} catch (err) {
				if (!settled) {
					settled = true;
					this.releaseInFlight(normalizedModuleKey);
				}
				throw err;
			}
		};
	}

	private consumeBucket(bucketKey: string, rule: RateLimitRule): { allowed: boolean; retryAfterMs: number } {
		const now = Date.now();
		const current = this.buckets.get(bucketKey);

		if (!current || now - current.windowStart >= rule.windowMs) {
			this.buckets.set(bucketKey, { windowStart: now, count: 1 });
			return { allowed: true, retryAfterMs: 0 };
		}

		if (current.count >= rule.maxRequests) {
			return {
				allowed: false,
				retryAfterMs: Math.max(0, current.windowStart + rule.windowMs - now)
			};
		}

		current.count++;
		return { allowed: true, retryAfterMs: 0 };
	}

	private recordDecision(_moduleKey: string, rpcName: string, allowed: boolean): void {
		if (allowed) this.metrics.allowed++;
		else this.metrics.blocked++;

		const byRpc = this.metrics.byRpc.get(rpcName) || { allowed: 0, blocked: 0 };
		if (allowed) byRpc.allowed++;
		else byRpc.blocked++;
		this.metrics.byRpc.set(rpcName, byRpc);
	}

	/**
	 * Instantánea del periodo y **puesta a cero**.
	 *
	 * Estas cuentas se llevaban desde el primer día y no las leía nadie: eran
	 * contabilidad muerta que se tiraba al morir el proceso. Se drenan en vez de
	 * acumularse desde el arranque porque lo que interesa es la TASA —«este minuto
	 * han entrado 6.900 y he bloqueado 12»—, no un total desde el último
	 * despliegue, que no dice nada de si algo va mal ahora.
	 *
	 * `topRpcs` sale ordenado por volumen y recortado: el objetivo es una línea de
	 * log legible, no un volcado de los cien RPCs del catálogo.
	 */
	public drainMetrics(topN = 3): {
		allowed: number;
		blocked: number;
		topRpcs: Array<{ rpc: string; allowed: number; blocked: number }>;
		/** Máximo de peticiones simultáneas de un módulo en el periodo. */
		inFlightPeak: number;
		/** Rechazos por techo de concurrencia en el periodo. */
		inFlightRejected: number;
	} {
		const topRpcs = [...this.metrics.byRpc.entries()]
			.map(([rpc, counts]) => ({ rpc, ...counts }))
			.sort((a, b) => b.allowed + b.blocked - (a.allowed + a.blocked))
			.slice(0, topN);
		const snapshot = {
			allowed: this.metrics.allowed,
			blocked: this.metrics.blocked,
			topRpcs,
			inFlightPeak: this.inFlightPeak,
			inFlightRejected: this.inFlightRejections
		};

		this.metrics.allowed = 0;
		this.metrics.blocked = 0;
		this.metrics.byRpc.clear();
		this.inFlightRejections = 0;
		// El pico se reinicia a lo que hay VIVO ahora, no a cero: si hay 40 peticiones
		// en vuelo en este instante, el pico del periodo siguiente no puede ser menor.
		this.inFlightPeak = this.getInFlight();

		return snapshot;
	}

	/**
	 * Evict buckets whose window has fully elapsed and which would be
	 * reset on the next call anyway. Without this, every distinct
	 * (module, rpc) pair seen since boot keeps a dead entry in the map.
	 * The next `consumeBucket` call resets entries it actually uses, so
	 * dropping them here only removes truly idle buckets.
	 */
	public sweepStaleBuckets(now: number = Date.now()): number {
		let removed = 0;
		for (const [key, state] of this.buckets) {
			const rule = key.startsWith("rpc:") ? this.rpcRules.get(key.split(":").slice(2).join(":")) : undefined;
			const windowMs = rule?.windowMs ?? this.moduleRule.windowMs;
			if (now - state.windowStart >= windowMs * 2) {
				this.buckets.delete(key);
				removed++;
			}
		}
		return removed;
	}
}

