1	// Import via require so vitest doesn't try to resolve the `.js` extension
2	// from the source — the file lives in `dist/`. This matches the pattern
3	// other pre-existing tests in this repo use to load compiled modules.
4	import { createRequire } from "node:module";
5	import type { MessageResponseIPC } from "@kena/shared";
6	import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
7	
8	const require = createRequire(import.meta.url);
9	const { RequestTracker } =
10		require("../../../../dist/cluster/master/ipc/RequestTracker.js") as typeof import("../../../../dist/cluster/master/ipc/RequestTracker.js");
11	
12	/**
13	 * Audit 1.6 — DEFER_TIMEOUT del master vs éxito real del worker
14	 *
15	 * The OLD code in InteractionGrpcService.forwardDeferWithBudget set up a
16	 * tracker with a tight budget. If the worker's POST to Discord finished
17	 * JUST after the tracker's timer fired:
18	 *   1. The tracker rejects with "Request X timed out after Yms".
19	 *   2. The worker's success response lands in
20	 *      `RequestTracker.resolveRequest`, which finds no pending entry and
21	 *      logs "Received response for unknown request" — response is lost.
22	 *   3. The SDK receives `DEFER_TIMEOUT` and sets `deferFailed = true`, so
