// Import via require so vitest doesn't try to resolve the `.js` extension
// from the source — the file lives in `dist/`. This matches the pattern
// other pre-existing tests in this repo use to load compiled modules.
import { createRequire } from "node:module";
import type { MessageResponseIPC } from "@kena/shared";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const require = createRequire(import.meta.url);
const { RequestTracker, pendingRequestsSnapshot } =
	require("../../../../dist/cluster/master/ipc/RequestTracker.js") as typeof import("../../../../dist/cluster/master/ipc/RequestTracker.js");

/**
 * Auditoría 2026-08-11 — techo de `pendingRequests`
 *
 * `pendingRequests` no tenía `maxPending`: si las peticiones entraban más
 * rápido de lo que el worker resolvía, el Map crecía sin límite, cada entrada
 * reteniendo su closure, su `Timeout`, y (indirectamente, vía el `await`
 * suspendido del llamante) el payload completo. Estos tests fijan el
 * contrato del techo: rechazo inmediato al llegar al tope, sin tocar las
 * entradas ya en vuelo, y visible via `pendingRequestsSnapshot`.
 */
describe("RequestTracker — techo de pendingRequests", () => {
	beforeEach(() => {
		vi.useFakeTimers();
	});

	afterEach(() => {
		vi.useRealTimers();
	});

	it("rejects a new request once the queue is at capacity, without touching what's already tracked", async () => {
		const tracker = new RequestTracker(30000, 2);

		const first = tracker.trackRequest("trace-1");
		const second = tracker.trackRequest("trace-2");
		expect(tracker.getPendingCount()).toBe(2);

		// A third request arrives while the first two are still pending: it
		// must be rejected immediately, not queued.
		await expect(tracker.trackRequest("trace-3")).rejects.toThrow(/at capacity/);
		expect(tracker.getPendingCount()).toBe(2);

		// The two already-tracked requests are unaffected by the rejection.
		const response: MessageResponseIPC = {
			success: true,
			data: { ok: true },
			timestamp: new Date().toISOString(),
			request_id: "trace-1"
		} as any;
		expect(tracker.resolveRequest("trace-1", response)).toBe(true);
		await expect(first).resolves.toEqual(response);
		expect(tracker.getPendingCount()).toBe(1);

		tracker.clearAll();
		await expect(second).rejects.toThrow();
	});

	it("frees a slot once a pending request settles, so a later request can be tracked again", async () => {
		const tracker = new RequestTracker(30000, 1);

		const first = tracker.trackRequest("trace-1");
		await expect(tracker.trackRequest("trace-2")).rejects.toThrow(/at capacity/);

		tracker.resolveRequest("trace-1", {
			success: true,
			data: {},
			timestamp: new Date().toISOString(),
			request_id: "trace-1"
		} as any);
		await first;
		expect(tracker.getPendingCount()).toBe(0);

		const third = tracker.trackRequest("trace-3");
		expect(tracker.getPendingCount()).toBe(1);
		tracker.clearAll();
		await expect(third).rejects.toThrow();
	});

	it("a colliding trace_id (superseding an existing entry) is never rejected by the ceiling", async () => {
		const tracker = new RequestTracker(30000, 1);

		const first = tracker.trackRequest("trace-1");
		// Same id again: this supersedes the prior entry instead of growing the
		// map, so it must succeed even though the tracker is at its cap of 1.
		const second = tracker.trackRequest("trace-1");
		expect(tracker.getPendingCount()).toBe(1);

		await expect(first).rejects.toThrow(/superseded/);
		tracker.clearAll();
		await expect(second).rejects.toThrow();
	});

	it("exposes ceiling rejections via pendingRequestsSnapshot, drained per call", async () => {
		const tracker = new RequestTracker(30000, 1);
		tracker.trackRequest("trace-1");
		await expect(tracker.trackRequest("trace-2")).rejects.toThrow(/at capacity/);
		await expect(tracker.trackRequest("trace-3")).rejects.toThrow(/at capacity/);

		const first = pendingRequestsSnapshot();
		expect(first.ceilingRejected).toBe(2);

		// Drained: a second read in the same period sees zero until a new
		// rejection happens.
		const second = pendingRequestsSnapshot();
		expect(second.ceilingRejected).toBe(0);

		tracker.clearAll();
	});
});

