46	export class RequestTracker {
47		private readonly pendingRequests = new Map<string, PendingRequest>();
48		/**
49		 * Audit 1.6: a small ring of late-arriving success responses for
50		 * requests that already timed out. We keep them around for a brief
51		 * window so the caller (InteractionGrpcService) can convert a
52		 * tracker-induced DEFER_TIMEOUT into a real success when the worker's
53		 * POST actually completed before Discord rejected anything.
54		 */
55		private readonly lateSuccesses = new Map<string, MessageResponseIPC>();
56		/**
57		 * Bounded so the ring can't grow under a sustained stream of late
58		 * successes. 256 is a comfortable upper bound for the rate at which
59		 * a worker might legitimately be late (we keep the most recent 256).
60		 */
61		private static readonly LATE_SUCCESS_MAX = 256;
62		/**
63		 * Techo de `pendingRequests` por defecto si el llamante no pasa uno.
64		 *
65		 * El freno de primera línea es `GrpcRateLimiter.maxInFlightPerModule` (256,
66		 * server.ts), pero es POR MÓDULO — y un `RequestTracker` es por SERVICIO,
67		 * compartido por los ~10 módulos del core. En el peor caso sano (los diez
68		 * módulos a la vez en su techo de concurrencia contra el mismo servicio) eso
69		 * es del orden de 2560 peticiones vivas. 3000 deja margen sobre esa cifra sin
70		 * dejar de ser un techo real: el incidente del 11-08-2026 llegó a ~575
71		 * peticiones vivas con el core ya inservible, así que muy por debajo de 3000
72		 * la memoria ya está descontrolada — este número es la red de seguridad para
73		 * cuando el freno por módulo falla, está mal calibrado, o no aplica (un
74		 * servicio sin rate limiter, por ejemplo).
75		 */
76		private static readonly DEFAULT_MAX_PENDING = 3000;
77		private readonly defaultTimeout: number;
78		private readonly maxPending: number;
79		/** Rechazos acumulados por techo de cola, drenados por `drainCeilingRejections`. */
80		private ceilingRejections = 0;
81		private onSettle?: (request_id: string) => void;
82		private onLateSuccess?: (request_id: string, response: MessageResponseIPC) => void;
83	
84		constructor(defaultTimeout = 30000, maxPending = RequestTracker.DEFAULT_MAX_PENDING) {
85			// 30 seconds default
86			this.defaultTimeout = defaultTimeout;
87			this.maxPending =
88				Number.isFinite(maxPending) && maxPending > 0 ? Math.floor(maxPending) : RequestTracker.DEFAULT_MAX_PENDING;
89			// Se apunta al registro para que la profundidad de la cola sea medible sin
90			// abrir un getter en cada servicio. Los trackers viven lo que el proceso, así
91			// que no hace falta darse de baja.
92			liveTrackers.add(this);
93		}
94	
95		/**
96		 * Register a callback fired whenever a request is fully settled (resolve,
97		 * reject, timeout, or supersede). Used by ClusterIPC to clear its
98		 * `pendingByCluster` rejector so a later cluster-exit doesn't try to
99		 * invoke a no-op `rejectRequest` and spam "Cannot reject unknown
100		 * request" warnings.
101		 */
102		setOnSettle(cb: (request_id: string) => void): void {
103			this.onSettle = cb;
104		}
105	
106		/**
107		 * Audit 1.6: register a callback fired when a success response arrives
108		 * for a request that has already timed out. The InteractionGrpcService
109		 * uses this to convert a tracker-induced DEFER_TIMEOUT into OK so the
110		 * SDK doesn't set deferFailed=true on a defer that actually succeeded.
111		 */
112		setOnLateSuccess(cb: (request_id: string, response: MessageResponseIPC) => void): void {
113			this.onLateSuccess = cb;
114		}
115	
116		/**
117		 * Track a request and return a promise that resolves when the response arrives
118		 */
119		trackRequest(request_id: string, timeoutMs?: number): Promise<MessageResponseIPC> {
120			// Collision: reject the previous holder immediately and clear its
121			// timer before installing the new one. Without this, the prior
122			// promise would leak until its 30s timer fires AND its expiry would
123			// delete the NEW entry — making the new caller's response land as
124			// "Received response for unknown request" and itself time out.
125			const prior = this.pendingRequests.get(request_id);
126			if (prior) {
127				clearTimeout(prior.timeout);
128				this.pendingRequests.delete(request_id);
129				prior.reject(new Error(`Request ${request_id} superseded by a new tracker entry (trace_id collision)`));
130				this.onSettle?.(request_id);
131				logger.warn(LogType.CLUSTER, `Request ${request_id} was already tracked — rejected the prior promise`);
132			}
133	
134			// Techo de cola: sin esto, un worker más lento que la entrada deja crecer
135			// el Map sin límite — cada entrada retiene su `resolve`/`reject`, el
136			// `Timeout`, y (vía el cierre del `await` suspendido en el llamante) el
137			// payload completo de la petición, hasta 16 MiB por
138			// `max_receive_message_length` (server.ts). Es el mismo patrón que
139			// `MessageIngestBuffer.maxBufferedMessages`: se rechaza la entrada NUEVA y
140			// se cuenta, en vez de dejar que el heap decida por nosotros.
141			if (this.pendingRequests.size >= this.maxPending) {
142				this.ceilingRejections++;
143				logger.warn(
144					LogType.CLUSTER,
145					`Request ${request_id} rejected: pending queue at capacity (${this.maxPending})`
146				);
147				return Promise.reject(
148					new Error(`Request ${request_id} rejected: pending request queue at capacity (${this.maxPending})`)
149				);
150			}
151	
152			return new Promise<MessageResponseIPC>((resolve, reject) => {
153				const timeout = setTimeout(() => {
154					this.pendingRequests.delete(request_id);
155					this.onSettle?.(request_id);
156					reject(new Error(`Request ${request_id} timed out after ${timeoutMs || this.defaultTimeout}ms`));
157				}, timeoutMs || this.defaultTimeout);
158	
159				this.pendingRequests.set(request_id, {
160					resolve,
161					reject,
162					timeout,
163					timestamp: Date.now()
164				});
165	
166				logger.info(
167					LogType.CLUSTER,
168					`Tracking request ${request_id} with timeout ${timeoutMs || this.defaultTimeout}ms`
169				);
170			});
171		}
172	
173		/**
174		 * Resolve a tracked request with a response
175		 */
176		resolveRequest(request_id: string, response: MessageResponseIPC): boolean {
177			const pending = this.pendingRequests.get(request_id);
178			if (!pending) {
179				// Audit 1.6: a success response arriving AFTER the tracker
180				// timed out used to be dropped silently. We now keep a
181				// bounded ring of late successes and fire the onLateSuccess
182				// hook so the caller can convert the timeout into OK. A
183				// failure response is still discarded — letting late
184				// failures slip through would let a real defer failure
185				// masquerade as a late success.
186				if (response?.success) {
187					this.recordLateSuccess(request_id, response);
188					logger.warn(LogType.CLUSTER, `[late_success] received success for already-settled request ${request_id}`);
189					this.onLateSuccess?.(request_id, response);
190				} else {
191					logger.warn(LogType.CLUSTER, `Received response for unknown request ${request_id}`);
192				}
193				return false;
194			}
195	
196			clearTimeout(pending.timeout);
197			this.pendingRequests.delete(request_id);
198			this.onSettle?.(request_id);
199	
200			const duration = Date.now() - pending.timestamp;
201			logger.info(LogType.CLUSTER, `Request ${request_id} resolved in ${duration}ms`);
202	
203			pending.resolve(response);
204			return true;
205		}
206	
207		/**
208		 * Audit 1.6: bounded ring of late-arriving success responses. The
209		 * oldest entry is evicted FIFO when the cap is hit so a sustained
210		 * stream of late successes can't grow the Map without bound.
211		 */
212		private recordLateSuccess(request_id: string, response: MessageResponseIPC): void {
213			if (this.lateSuccesses.size >= RequestTracker.LATE_SUCCESS_MAX) {
214				const oldest = this.lateSuccesses.keys().next().value;
215				if (oldest !== undefined) this.lateSuccesses.delete(oldest);
216			}
217			this.lateSuccesses.set(request_id, response);
218		}
219	
220		/**
221		 * Audit 1.6: lookup (and clear) a late success. The InteractionGrpcService
222		 * calls this from its catch block after a tracker-timeout to check
223		 * whether the worker actually completed the defer despite the timer.
224		 */
225		consumeLateSuccess(request_id: string): MessageResponseIPC | null {
226			const response = this.lateSuccesses.get(request_id);
227			if (response) this.lateSuccesses.delete(request_id);
228			return response ?? null;
229		}
230	
231		/**
232		 * Reject a tracked request with an error
233		 */
234		rejectRequest(request_id: string, error: Error): boolean {
235			const pending = this.pendingRequests.get(request_id);
236			if (!pending) {
237				logger.warn(LogType.CLUSTER, `Cannot reject unknown request ${request_id}`);
238				return false;
239			}
240	
241			clearTimeout(pending.timeout);
242			this.pendingRequests.delete(request_id);
243			this.onSettle?.(request_id);
244	
245			logger.error(LogType.CLUSTER, `Request ${request_id} rejected:`, error);
246	
247			pending.reject(error);
248			return true;
249		}
250	
251		/**
252		 * Get the number of pending requests
253		 */
254		getPendingCount(): number {
255			return this.pendingRequests.size;
256		}
257	
258		/**
259		 * Instantánea de rechazos por techo de cola desde el último drenaje, y
260		 * **puesta a cero**. Igual que `GrpcRateLimiter.drainMetrics`: lo que
261		 * interesa en el log periódico es la tasa del periodo, no un total desde el
262		 * arranque que no dice nada de si algo va mal ahora.
263		 */
264		drainCeilingRejections(): number {
265			const n = this.ceilingRejections;
266			this.ceilingRejections = 0;
267			return n;
268		}
269	
270		/**
271		 * Clear all pending requests (useful for testing or shutdown)
272		 */
273		clearAll(): void {
274			for (const pending of this.pendingRequests.values()) {
275				clearTimeout(pending.timeout);
276				pending.reject(new Error("Request tracker cleared"));
277			}
278			this.pendingRequests.clear();
279			this.lateSuccesses.clear();
280			logger.info(LogType.CLUSTER, "All pending requests cleared");
281		}
282	}
